"use strict";

import { ErdstallObject, registerErdstallType } from "#erdstall/api";
import { CodecReader, CodecWriter } from "#erdstall/utils";

const phaseShiftTypeName = "PhaseShift";

// A BalanceProof is generated by the Enclave at the end of each transaction
// phase for each account in the Erdstall system.
export class PhaseShift extends ErdstallObject {
		constructor(
	public currentEpoch: bigint
		) { super(); }

	override objectType(): any { return PhaseShift; }
	override objectTypeName(): string { return phaseShiftTypeName; }

	override encode(w: CodecWriter): void { w.u64(this.currentEpoch); }
	static decode(r: CodecReader): PhaseShift
		{ return new PhaseShift(r.u64()); }
}

registerErdstallType(phaseShiftTypeName, PhaseShift);
